import { useState, type FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

export interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
}

export interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

const summaryLabels: Array<[keyof RegistrationData, string]> = [
  ['name', 'Имя'],
  ['email', 'Электронная почта'],
  ['phone', 'Телефон'],
  ['city', 'Город'],
  ['street', 'Улица и дом'],
  ['zip', 'Индекс'],
];

function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);

  const update = (field: keyof RegistrationData) => (event: { target: { value: string } }) => {
    setData((current) => ({ ...current, [field]: event.target.value }));
  };

  const isLast = step === steps.length - 1;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isLast) {
      setStep((current) => current + 1);
      return;
    }
    onSubmit(data);
  };

  return (
    <form onSubmit={submit} style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={update('name')}
            placeholder="Как к вам обращаться"
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={update('email')}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={data.phone}
            onChange={update('phone')}
            helperText="Только для важных уведомлений"
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField label="Город" required value={data.city} onChange={update('city')} />
          <JxInputField label="Улица и дом" required value={data.street} onChange={update('street')} />
          <JxInputField
            label="Индекс"
            inputMode="numeric"
            maxLength={6}
            value={data.zip}
            onChange={update('zip')}
          />
        </div>
      )}

      {step === 2 && (
        <dl
          style={{
            display: 'grid',
            gridTemplateColumns: 'auto 1fr',
            gap: '8px 16px',
            margin: 0,
            fontFamily: 'var(--jx-font-sans)',
          }}
        >
          {summaryLabels.map(([field, label]) => (
            <div key={field} style={{ display: 'contents' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>{label}</dt>
              <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{data[field] || '—'}</dd>
            </div>
          ))}
        </dl>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton
          type="button"
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep((current) => Math.max(current - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

export default RegistrationWizard;

